body.script:
(function () {
    var MODEL_URL = document.getElementById('config').getAttribute('data-model-url');
    var video = document.getElementById('video');
    var overlay = document.getElementById('overlay');
    var statusEl = document.getElementById('status');
    var lastActionAt = {};
    var COOLDOWN_MS = 8000;
    var MATCH_DISTANCE = 0.5;

    function setStatus(text, cls) {
        statusEl.textContent = text;
        statusEl.className = cls || 'info';
    }

    function jsonrpc(route, params) {
        return fetch(route, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: params || {}, id: Date.now() }),
        }).then(function (r) { return r.json(); }).then(function (data) {
            if (data.error) { throw new Error(data.error.data && data.error.data.message || 'Server error'); }
            return data.result;
        });
    }

    function dominantExpression(expressions) {
        var best = null, bestScore = -1;
        Object.keys(expressions).forEach(function (key) {
            if (expressions[key] > bestScore) { bestScore = expressions[key]; best = key; }
        });
        return { mood: best, confidence: bestScore };
    }

    async function loadModels() {
        await faceapi.nets.tinyFaceDetector.loadFromUri(MODEL_URL);
        await faceapi.nets.faceLandmark68TinyNet.loadFromUri(MODEL_URL);
        await faceapi.nets.faceRecognitionNet.loadFromUri(MODEL_URL);
        await faceapi.nets.faceExpressionNet.loadFromUri(MODEL_URL);
    }

    function cameraErrorMessage(e) {
        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
            return 'This browser/app cannot access the camera (no camera API available).';
        }
        var name = e && e.name;
        if (name === 'NotAllowedError' || name === 'PermissionDeniedError') {
            return 'Camera access was denied. Please allow camera permission for this page in your browser/app settings, then reload.';
        }
        if (name === 'NotFoundError' || name === 'DevicesNotFoundError') {
            return 'No camera was found on this device.';
        }
        if (name === 'NotReadableError' || name === 'TrackStartError') {
            return 'The camera is closed, disconnected, or already being used by another app.';
        }
        if (name === 'OverconstrainedError' || name === 'ConstraintNotSatisfiedError') {
            return 'No camera on this device matches the required settings.';
        }
        if (name === 'SecurityError') {
            return 'Camera access is blocked - this page must be opened over HTTPS (or localhost).';
        }
        return 'Could not access the camera' + (e && e.message ? ': ' + e.message : '.');
    }

    async function startCamera() {
        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
            throw new Error(cameraErrorMessage());
        }
        var stream;
        try {
            stream = await navigator.mediaDevices.getUserMedia({ video: {} });
        } catch (e) {
            throw new Error(cameraErrorMessage(e));
        }
        video.srcObject = stream;
        return new Promise(function (resolve) { video.onloadedmetadata = resolve; });
    }

    async function buildMatcher() {
        var employees = await jsonrpc('/hr_face_mood/descriptors', {});
        if (!employees.length) {
            setStatus('No enrolled, consenting employees found yet.', 'err');
            return null;
        }
        var labeled = employees.map(function (e) {
            return new faceapi.LabeledFaceDescriptors(String(e.id), [new Float32Array(e.descriptor)]);
        });
        var byId = {};
        employees.forEach(function (e) { byId[e.id] = e.name; });
        return { matcher: new faceapi.FaceMatcher(labeled, MATCH_DISTANCE), names: byId };
    }

    async function loop(matcherData) {
        var detectorOpts = new faceapi.TinyFaceDetectorOptions();
        overlay.width = video.clientWidth;
        overlay.height = video.clientHeight;
        var busy = false;

        var intervalId = setInterval(async function () {
            if (busy) { return; }
            busy = true;
            var result = await faceapi
                .detectSingleFace(video, detectorOpts)
                .withFaceLandmarks(true)
                .withFaceExpressions()
                .withFaceDescriptor();

            var ctx = overlay.getContext('2d');
            ctx.clearRect(0, 0, overlay.width, overlay.height);

            if (!result) {
                setStatus('Looking for a face…', 'info');
                busy = false;
                return;
            }

            var match = matcherData.matcher.findBestMatch(result.descriptor);
            if (match.label === 'unknown') {
                setStatus('Face not recognized.', 'err');
                busy = false;
                return;
            }

            var employeeId = match.label;
            var now = Date.now();
            if (lastActionAt[employeeId] && (now - lastActionAt[employeeId]) < COOLDOWN_MS) {
                setStatus('Hi ' + matcherData.names[employeeId] + ', already recorded - thanks!', 'ok');
                busy = false;
                return;
            }

            var exp = dominantExpression(result.expressions);
            setStatus('Recognized ' + matcherData.names[employeeId] + '… recording ' + exp.mood + '…', 'info');

            try {
                var res = await jsonrpc('/hr_face_mood/attendance', {
                    employee_id: employeeId,
                    mood: exp.mood,
                    confidence: exp.confidence,
                    match_distance: match.distance,
                });
                if (res.success) {
                    lastActionAt[employeeId] = now;
                    var verb = res.action === 'check_in' ? 'checked in' : 'checked out';
                    setStatus(res.employee_name + ' ' + verb + ' (' + exp.mood + ')… Returning to Home…', 'ok');
                    clearInterval(intervalId);
                    setTimeout(function () { window.location.href = '/web'; }, 1500);
                    return;
                } else {
                    setStatus(res.error || 'Could not record attendance.', 'err');
                }
            } catch (e) {
                setStatus('Error: ' + e.message, 'err');
            }
            busy = false;
        }, 1500);
    }

    (async function main() {
        try {
            await loadModels();
            await startCamera();
            setStatus('Loading employee roster…', 'info');
            var matcherData = await buildMatcher();
            if (!matcherData) { return; }
            setStatus('Ready. Look at the camera.', 'ok');
            loop(matcherData);
        } catch (e) {
            setStatus('Startup error: ' + e.message, 'err');
        }
    })();
})();

t.script:
(function () {
    var MODEL_URL = document.getElementById('config').getAttribute('data-model-url');
    var video = document.getElementById('video');
    var btn = document.getElementById('capture-btn');
    var statusEl = document.getElementById('status');

    function setStatus(text, cls) {
        statusEl.textContent = text;
        statusEl.className = cls || 'info';
    }

    function jsonrpc(route, params) {
        return fetch(route, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: params || {}, id: Date.now() }),
        }).then(function (r) { return r.json(); }).then(function (data) {
            if (data.error) { throw new Error(data.error.data && data.error.data.message || 'Server error'); }
            return data.result;
        });
    }

    async function loadModels() {
        await faceapi.nets.tinyFaceDetector.loadFromUri(MODEL_URL);
        await faceapi.nets.faceLandmark68TinyNet.loadFromUri(MODEL_URL);
        await faceapi.nets.faceRecognitionNet.loadFromUri(MODEL_URL);
    }

    function cameraErrorMessage(e) {
        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
            return 'This browser/app cannot access the camera (no camera API available).';
        }
        var name = e && e.name;
        if (name === 'NotAllowedError' || name === 'PermissionDeniedError') {
            return 'Camera access was denied. Please allow camera permission for this page in your browser/app settings, then reload.';
        }
        if (name === 'NotFoundError' || name === 'DevicesNotFoundError') {
            return 'No camera was found on this device.';
        }
        if (name === 'NotReadableError' || name === 'TrackStartError') {
            return 'The camera is closed, disconnected, or already being used by another app.';
        }
        if (name === 'OverconstrainedError' || name === 'ConstraintNotSatisfiedError') {
            return 'No camera on this device matches the required settings.';
        }
        if (name === 'SecurityError') {
            return 'Camera access is blocked - this page must be opened over HTTPS (or localhost).';
        }
        return 'Could not access the camera' + (e && e.message ? ': ' + e.message : '.');
    }

    async function startCamera() {
        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
            throw new Error(cameraErrorMessage());
        }
        var stream;
        try {
            stream = await navigator.mediaDevices.getUserMedia({ video: {} });
        } catch (e) {
            throw new Error(cameraErrorMessage(e));
        }
        video.srcObject = stream;
        return new Promise(function (resolve) { video.onloadedmetadata = resolve; });
    }

    btn.addEventListener('click', async function () {
        btn.disabled = true;
        setStatus('Capturing…', 'info');
        try {
            var result = await faceapi
                .detectSingleFace(video, new faceapi.TinyFaceDetectorOptions())
                .withFaceLandmarks(true)
                .withFaceDescriptor();
            if (!result) {
                setStatus('No face detected - try again with better lighting.', 'err');
                btn.disabled = false;
                return;
            }
            var descriptor = Array.prototype.slice.call(result.descriptor);
            var res = await jsonrpc('/hr_face_mood/enroll', { descriptor: descriptor });
            if (res.success) {
                setStatus('Face enrolled successfully! Returning to Home…', 'ok');
                setTimeout(function () { window.location.href = '/web'; }, 1500);
                return;
            } else {
                setStatus('Could not save your face.', 'err');
            }
        } catch (e) {
            setStatus('Error: ' + e.message, 'err');
        } finally {
            btn.disabled = false;
        }
    });

    (async function main() {
        try {
            await loadModels();
            await startCamera();
            setStatus('Ready - click capture when you are facing the camera.', 'ok');
            btn.disabled = false;
        } catch (e) {
            setStatus('Startup error: ' + e.message, 'err');
        }
    })();
})();
